        public static byte[] HexStringToByteArray(string hexString)
        {
            hexString = hexString.Replace(" ", "").Replace(",", "");
            if (hexString.Length % 2 != 0)
                throw new ArgumentException("Hex string must have an even length.");
            byte[] returnBytes = new byte[hexString.Length / 2];
            for (int i = 0; i < returnBytes.Length; i++)
                returnBytes[i] = Convert.ToByte(hexString.Substring(i * 2, 2), 16);
            return returnBytes;
        }
        public static uint[] ByteArrayToUintArray(byte[] byteArray)
        {
            if (byteArray.Length % 4 != 0)
            {
                throw new ArgumentException("The length of byteArray must be a multiple of 4.");
            }
            int uintArrayLength = byteArray.Length / 4;
            uint[] uintArray = new uint[uintArrayLength];
            Buffer.BlockCopy(byteArray, 0, uintArray, 0, byteArray.Length);
            return uintArray;
        }
        public static void RenameKey<TKey, TValue>(Dictionary<TKey, TValue> dictionary, TKey oldKey, TKey newKey)
        {
            if (dictionary.ContainsKey(oldKey) && !dictionary.ContainsKey(newKey))
            {
                TValue value = dictionary[oldKey];
                dictionary.Remove(oldKey);
                dictionary.Add(newKey, value);
            }
        }

